-- Datenbank, wie sie der Sequelize-Stand (main bis Phase 2 Teil 1) angelegt hat: Schema, Indizes, Trigger,
-- Formate (Zeitpunkte als Text mit +00:00). 3 Benutzer, 41 Zeiteinträge, 2 Abschlüsse, Sitzungen, Protokoll.
CREATE TABLE `Users` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `email` VARCHAR(255) NOT NULL UNIQUE, `password` VARCHAR(255) NOT NULL, `name` VARCHAR(255) NOT NULL, `role` TEXT NOT NULL DEFAULT 'mitarbeiter', `isActive` TINYINT(1) DEFAULT 1, `stundenlohn` DECIMAL(8,2) DEFAULT 12, `abrechnungStart` INTEGER NOT NULL DEFAULT 1, `abrechnungEnde` INTEGER NOT NULL DEFAULT 31, `lohnzettelEmail` VARCHAR(255), `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `MinijobSettings` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `monthlyLimit` DECIMAL(10,2) NOT NULL, `description` VARCHAR(500) NOT NULL, `validFrom` DATE NOT NULL, `validUntil` DATE, `isActive` TINYINT(1) DEFAULT 0, `createdBy` INTEGER NOT NULL REFERENCES `Users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `TimeEntries` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `userId` INTEGER NOT NULL REFERENCES `Users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `clientId` VARCHAR(64), `date` DATE NOT NULL, `startTime` TIME NOT NULL, `endTime` TIME NOT NULL, `breakMinutes` INTEGER NOT NULL DEFAULT 30, `description` VARCHAR(500), `hourlyRateCents` INTEGER, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `AuditLogs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `actorId` INTEGER, `actorEmail` VARCHAR(255) NOT NULL DEFAULT 'system', `action` VARCHAR(64) NOT NULL, `entityType` VARCHAR(64) NOT NULL, `entityId` INTEGER, `targetUserId` INTEGER, `before` TEXT, `after` TEXT, `meta` TEXT, `createdAt` DATETIME NOT NULL);
CREATE TABLE `PeriodClosures` (`id` INTEGER PRIMARY KEY AUTOINCREMENT, `userId` INTEGER NOT NULL REFERENCES `Users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `periodStart` DATE NOT NULL, `periodEnd` DATE NOT NULL, `closedBy` INTEGER, `closedAt` DATETIME NOT NULL, `entryCount` INTEGER NOT NULL DEFAULT 0, `totalMinutes` INTEGER NOT NULL DEFAULT 0, `earningsCents` INTEGER NOT NULL DEFAULT 0, `limitCents` INTEGER NOT NULL, `carryInCents` INTEGER NOT NULL DEFAULT 0, `paidCents` INTEGER NOT NULL DEFAULT 0, `carryOutCents` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `Sessions` (`id` VARCHAR(36) PRIMARY KEY, `userId` INTEGER NOT NULL REFERENCES `Users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, `refreshHash` VARCHAR(64) NOT NULL, `previousHash` VARCHAR(64), `rotatedAt` DATETIME, `lastUsedAt` DATETIME NOT NULL, `expiresAt` DATETIME NOT NULL, `absoluteExpiresAt` DATETIME NOT NULL, `revokedAt` DATETIME, `revokedReason` VARCHAR(64), `clientType` VARCHAR(8) NOT NULL DEFAULT 'web', `deviceName` VARCHAR(100), `ip` VARCHAR(64), `userAgent` VARCHAR(255), `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL);
CREATE TABLE `LoginThrottles` (`email` VARCHAR(255) PRIMARY KEY, `failures` INTEGER NOT NULL DEFAULT 0, `lastFailureAt` DATETIME, `lockedUntil` DATETIME);
CREATE UNIQUE INDEX `users_email` ON `Users` (`email`);
CREATE INDEX `users_role` ON `Users` (`role`);
CREATE INDEX `users_is_active` ON `Users` (`isActive`);
CREATE INDEX `minijob_settings_valid_from` ON `MinijobSettings` (`validFrom`);
CREATE INDEX `minijob_settings_is_active` ON `MinijobSettings` (`isActive`);
CREATE INDEX `minijob_settings_valid_from_valid_until` ON `MinijobSettings` (`validFrom`, `validUntil`);
CREATE INDEX `minijob_settings_created_by` ON `MinijobSettings` (`createdBy`);
CREATE UNIQUE INDEX `unique_user_date` ON `TimeEntries` (`userId`, `date`);
CREATE UNIQUE INDEX `unique_user_client_id` ON `TimeEntries` (`userId`, `clientId`);
CREATE INDEX `time_entries_date` ON `TimeEntries` (`date`);
CREATE INDEX `audit_logs_created_at` ON `AuditLogs` (`createdAt`);
CREATE INDEX `audit_logs_target_user_id_created_at` ON `AuditLogs` (`targetUserId`, `createdAt`);
CREATE INDEX `audit_logs_entity_type_entity_id` ON `AuditLogs` (`entityType`, `entityId`);
CREATE INDEX `audit_logs_action` ON `AuditLogs` (`action`);
CREATE UNIQUE INDEX `unique_user_period_start` ON `PeriodClosures` (`userId`, `periodStart`);
CREATE INDEX `period_closures_user_id_period_end` ON `PeriodClosures` (`userId`, `periodEnd`);
CREATE INDEX `sessions_user_id` ON `Sessions` (`userId`);
CREATE INDEX `sessions_revoked_at` ON `Sessions` (`revokedAt`);
CREATE INDEX `sessions_absolute_expires_at` ON `Sessions` (`absoluteExpiresAt`);
CREATE TRIGGER auditlogs_no_update BEFORE UPDATE ON AuditLogs
    BEGIN SELECT RAISE(ABORT, 'AuditLogs sind unveränderlich'); END;
CREATE TRIGGER auditlogs_no_delete BEFORE DELETE ON AuditLogs
    BEGIN SELECT RAISE(ABORT, 'AuditLogs sind unveränderlich'); END;
